"""Project adapter starter for observatory assistant.
REQUIRES REVIEW: starter template only, not approved policy.
Uses existing semantic runtime only. Does not modify rules.
"""
from typing import Any, Dict, Optional, Tuple
import loader

APPROVED_INTENTS = ("target", "roster", "visitor", "safety-check")

def resolve_intent(context: Dict[str, Any]) -> Tuple[Optional[str], Optional[str]]:
    """Map deskPhase to an approved workflow intent."""
    phase = (context or {}).get("deskPhase")
    if phase == "target-selection":
        return ("target", None)
    if phase == "roster-collection":
        return ("roster", None)
    if phase in ("visitor-checkin", "visit"):
        return ("visitor", None)
    if phase in ("inspection", "safety-check"):
        return ("safety-check", None)
    return (None, "Missing deskPhase: ask which desk phase applies (target-selection, roster-collection, visitor-checkin, inspection).")

def observatory_request(context: Dict[str, Any], utterance: str, baseline: bool = False) -> Dict[str, Any]:
    """Single semantic-runtime call. Stops if no messages are returned."""
    if not isinstance(context, dict) or "deskPhase" not in context or "domeState" not in context:
        return {
            "action": "clarify",
            "message": "Need deskPhase and domeState to route. Please supply both.",
            "messages": [],
        }
    intent, clarification = resolve_intent(context)
    if intent is None:
        return {"action": "clarify", "message": clarification, "messages": []}
    if intent not in APPROVED_INTENTS:
        return {"action": "clarify", "message": "Unknown phase. Please clarify.", "messages": []}
    # First two args positionally per contract: (context, utterance).
    result = loader.runtime_request(context, utterance, baseline=baseline, intent=intent)
    # Do not bypass unresolved state or hash checks.
    if isinstance(result, dict):
        msgs = result.get("messages", result.get("prompt_messages", []))
        status = result.get("status", "ok")
        if status != "ok" or not msgs:
            return {
                "action": "clarify",
                "message": "Runtime returned no usable context. Resolve state or hash issue before continuing.",
                "messages": [],
                "detail": result,
            }
        return {"action": "runtime", "messages": msgs, "detail": result}
    if not result:
        return {"action": "clarify", "message": "No runtime messages. Stopping without bypass.", "messages": []}
    return {"action": "runtime", "messages": result}
